import os, requests
os.chdir('/home/data4/xiangyu/BioDSA/workdir')
terms=['"Descriptive study of healthcare professionals" tick bite','healthcare professionals management tick bite','physicians management tick bites','tick bite management healthcare professionals']
for term in terms:
    url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
    try:
        r=requests.get(url,params={'db':'pubmed','term':term,'retmode':'json','retmax':5},timeout=20)
        r.raise_for_status()
        ids=r.json()['esearchresult']['idlist']
        print('\nQUERY:',term,'\nPMIDS:',ids)
        if ids:
            f=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20)
            f.raise_for_status()
            for k,v in f.json().get('result',{}).items():
                if k!='uids': print(k, v.get('title'), '|', v.get('pubdate'), '|', v.get('fulljournalname'), '| DOI', v.get('elocationid'))
    except Exception as e:
        print('QUERY ERROR:',term,repr(e))
print('\nResearch log: queried PubMed E-utilities for exact-title and topic variants.')
print('Working directory:',os.getcwd())
